mapper.select:
select t.pk_id, t.project_code, t.project_name, d.location competent_name, t.competent_dept, t.sys_no, t.sys_name, t.start_date, t.end_date, t.create_by, t.create_date, t.update_by, t.update_date, t.project_state, t.head_user, t.dev_user, t.deleted, t.participating_dept, t.bus_innova, t.tech_innova from ppm.rd_project t left join ppm.comm_rd_department d on (d.depid = t.competent_dept) where t.DELETED='0' and t.project_code like '%'||#{projectCode}||'%' and t.project_name like '%'||#{projectName}||'%' and t.competent_dept like '%'||#{competentDept}||'%'
and t.sys_name like '%'||#{sysName}||'%'
and not exists(select 1 from ppm.rd_project_contract_relation r where r.rd_project_contract_id = #{notRdProjectContractId} and r.rd_project_id=t.pk_id)
order by t.${prop} ${order}
order by ${prop} ${order}
order by t.project_code desc
